// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address[] memory tos, uint[] memory vals) public {
        vm.assume(tos.length > 0);
        vm.assume(tos.length == vals.length);
        // keep amounts in a wide admissible range to avoid overflow in mul_uint256
        for (uint i = 0; i < vals.length; i++) {
            vals[i] = bound(vals[i], 0, 1000 ether);
        }

        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool ok = c.transfer(tos, vals);

        // General rule: a completed call to transfer always returns true.
        assertTrue(ok);
    }
}
